import{_ as e,o as n,c as o,a2 as r}from"./chunks/framework.A5mep7Fe.js";const c=JSON.parse('{"title":"🔗 04 · MCP 与多 Agent（Multi-Agent）","description":"","frontmatter":{},"headers":[],"relativePath":"03-算法岗-AI-Agent/04-MCP与多Agent.md","filePath":"03-算法岗-AI-Agent/04-MCP与多Agent.md","lastUpdated":1786806808000}'),a={name:"03-算法岗-AI-Agent/04-MCP与多Agent.md"};function l(g,t,i,s,d,h){return n(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="🔗-04-·-mcp-与多-agent-multi-agent" tabindex="-1">🔗 04 · MCP 与多 Agent（Multi-Agent） <a class="header-anchor" href="#🔗-04-·-mcp-与多-agent-multi-agent" aria-label="Permalink to &quot;🔗 04 · MCP 与多 Agent（Multi-Agent）&quot;">​</a></h1><blockquote><p>当单个 Agent 不够用时：用 MCP 标准化工具接入，用多 Agent 协作分工。本篇讲「规模化」。</p></blockquote><hr><h2 id="一、mcp-model-context-protocol" tabindex="-1">一、MCP（Model Context Protocol） <a class="header-anchor" href="#一、mcp-model-context-protocol" aria-label="Permalink to &quot;一、MCP（Model Context Protocol）&quot;">​</a></h2><p><strong>问题</strong>：每个 Agent 框架都要自己写工具适配，工具无法复用、生态割裂。</p><p><strong>MCP 的思想</strong>：定义一套<strong>标准化协议</strong>，让「模型」与「工具/数据源」解耦——就像 USB-C 统一接口。</p><ul><li><strong>MCP Server</strong>：暴露工具/资源（如查数据库、读文件、调 API）</li><li><strong>MCP Client</strong>：Agent 通过标准协议调用 Server</li><li><strong>好处</strong>：工具一次开发，任意兼容 MCP 的 Agent 都能用；安全边界清晰</li></ul><blockquote><p>本质判断：MCP 是「工具接入标准」，不是 Agent 框架本身。它解决的是<strong>互操作性与复用</strong>，跨周期价值在于「降低集成成本」。</p></blockquote><hr><h2 id="二、多-agent-协作-multi-agent" tabindex="-1">二、多 Agent 协作（Multi-Agent） <a class="header-anchor" href="#二、多-agent-协作-multi-agent" aria-label="Permalink to &quot;二、多 Agent 协作（Multi-Agent）&quot;">​</a></h2><p><strong>动机</strong>：单 Agent 上下文有限、易顾此失彼；分工可提升复杂任务质量。</p><h3 id="常见协作模式" tabindex="-1">常见协作模式 <a class="header-anchor" href="#常见协作模式" aria-label="Permalink to &quot;常见协作模式&quot;">​</a></h3><ol><li><strong>主管-下属（Supervisor-Worker）</strong>：一个 Orchestrator 拆解任务，派给专门 Agent（检索/编码/写作）。</li><li><strong>流水线（Pipeline）</strong>：Agent A 产出 → Agent B 消费，串行。</li><li><strong>辩论/评审（Debate）</strong>：多个 Agent 各执观点，互评收敛（提升推理质量）。</li><li><strong>角色扮演</strong>：不同专家角色协作（如产品经理+工程师+测试）。</li></ol><h3 id="通信机制" tabindex="-1">通信机制 <a class="header-anchor" href="#通信机制" aria-label="Permalink to &quot;通信机制&quot;">​</a></h3><ul><li>共享黑板（Blackboard）/ 消息总线</li><li>结构化消息（JSON）、共享记忆</li><li>主管调度或事件驱动</li></ul><h3 id="冲突与协调" tabindex="-1">冲突与协调 <a class="header-anchor" href="#冲突与协调" aria-label="Permalink to &quot;冲突与协调&quot;">​</a></h3><ul><li><strong>任务冲突</strong>：主管仲裁、优先级队列</li><li><strong>结果不一致</strong>：投票/评审/一致性校验</li><li><strong>上下文膨胀</strong>：每个子 Agent 只看自己相关上下文，主管汇总</li></ul><hr><h2 id="三、何时用多-agent-避免过度设计" tabindex="-1">三、何时用多 Agent？（避免过度设计） <a class="header-anchor" href="#三、何时用多-agent-避免过度设计" aria-label="Permalink to &quot;三、何时用多 Agent？（避免过度设计）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>用单 Agent</th><th>用多 Agent</th></tr></thead><tbody><tr><td>任务单一、工具少</td><td>任务复杂需分工</td></tr><tr><td>成本/延迟敏感</td><td>质量优先、可并行</td></tr><tr><td>快速原型</td><td>生产级、需专业化</td></tr></tbody></table><p><strong>成本提醒</strong>：多 Agent = 多轮 LLM 调用，token 成本和延迟显著上升。先问「单 Agent + 好工具」能否解决。</p><hr><h2 id="四、高频追问" tabindex="-1">四、高频追问 <a class="header-anchor" href="#四、高频追问" aria-label="Permalink to &quot;四、高频追问&quot;">​</a></h2><p><strong>Q1：MCP 解决了什么痛点？</strong></p><blockquote><p>工具/数据源与 Agent 强耦合、无法复用。MCP 用标准协议解耦，一次开发多端复用，降低集成成本、明确安全边界。</p></blockquote><p><strong>Q2：多 Agent 一定比单 Agent 好吗？</strong></p><blockquote><p>不一定。多 Agent 增加成本和复杂度，只在「确实需要分工/并行/专业化」时收益明显；很多场景单 Agent + 好工具 + 反思即够用。</p></blockquote><p><strong>Q3：多 Agent 怎么解决冲突？</strong></p><blockquote><p>主管仲裁、结果评审/投票、共享一致记忆、明确各 Agent 职责边界，必要时加校验 Agent。</p></blockquote><hr><p>➡️ 下一步：<a href="./05-Agent工程化与评估">05-Agent 工程化与评估</a></p>',31)])])}const u=e(a,[["render",l]]);export{c as __pageData,u as default};
